      var groups = section.querySelectorAll('[data-group]');
      var countEl = document.getElementById('kk-menu-count');
      var labels = { all: 'all dishes', veg: 'veg dishes', nonveg: 'non-veg dishes' };

      function applyFilter(mode) {
        var shown = 0;
        Array.prototype.forEach.call(dishes, function (dish) {
          var match = mode === 'all' || dish.getAttribute('data-diet') === mode;
          dish.hidden = !match;
          if (match) { shown += 1; }
        });
        Array.prototype.forEach.call(groups, function (group) {
          var visible = group.querySelectorAll('.kk-dish:not([hidden])').length;
          group.hidden = visible === 0;
        });
        Array.prototype.forEach.call(buttons, function (btn) {
          var active = btn.getAttribute('data-filter') === mode;
          btn.setAttribute('aria-pressed', active ? 'true' : 'false');
          btn.className = active ? 'j2-btn' : 'j2-btn-secondary';
        });
        if (countEl) {
          countEl.textContent = 'Showing ' + shown + ' ' + (labels[mode] || labels.all);
        }
      }

      Array.prototype.forEach.call(buttons, function (btn) {
        btn.addEventListener('click', function () {
          applyFilter(btn.getAttribute('data-filter'));
        });
      });

      applyFilter('all');
    })();
  </script>
